<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { CreateTask, CreateUnit, ExportData, GetDefaultUnitID, ImportData, ListTasks, ListUnits, SetDefaultUnit, UpdateTask, UpdateTaskStatus, UpdateUnit } from '../wailsjs/go/main/App'
type Status = 'in_progress'|'completed'|'cancelled'; type TaskType='code'|'document'|'support'; type Kind='main'|'branch'
type Task={id:string;name:string;kind:Kind;parentId:string;issuer:string;unit:string;publishDate:string;dueDate:string;taskType:TaskType;status:Status;deliverable:string;summary:string;createdAt:string;updatedAt:string}
type Unit={id:string;name:string}
const tasks=ref<Task[]>([]), units=ref<Unit[]>([]), defaultUnitID=ref(''), selected=ref<Task|null>(null), showCreate=ref(false), showUnits=ref(false), newUnit=ref(''), message=ref(''), query=ref(''), status=ref('all'), type=ref('all')
const today=()=>new Date().toISOString().slice(0,10)
const draft=reactive({name:'',kind:'main' as Kind,parentId:'',issuer:'',unit:'',publishDate:today(),dueDate:today(),taskType:'code' as TaskType})
const statusText:Record<Status,string>={in_progress:'进行中',completed:'已完成',cancelled:'已取消'}; const typeText:Record<TaskType,string>={code:'代码',document:'文档',support:'支持'}
const mains=computed(()=>tasks.value.filter(t=>t.kind==='main')); const filtered=computed(()=>tasks.value.filter(t=>(status.value==='all'||t.status===status.value)&&(type.value==='all'||t.taskType===type.value)&&`${t.name} ${t.issuer} ${t.unit}`.toLowerCase().includes(query.value.toLowerCase())))
const overdue=(t:Task)=>t.status==='in_progress'&&t.dueDate<today(); const isVisible=(t:Task)=>filtered.value.some(x=>x.id===t.id)||tasks.value.some(x=>x.kind==='branch'&&x.parentId===t.id&&filtered.value.some(y=>y.id===x.id))
async function refresh(){const [all, unitList, defaultID]=await Promise.all([ListTasks(),ListUnits(),GetDefaultUnitID()]);tasks.value=(all??[]) as Task[];units.value=(unitList??[]) as Unit[];defaultUnitID.value=defaultID||'';if(selected.value)selected.value=tasks.value.find(t=>t.id===selected.value?.id)||null;else selected.value=tasks.value[0]||null}
function openCreate(){if(!units.value.length){showUnits.value=true;message.value='请先创建一个单位';return} draft.unit=units.value.find(u=>u.id===defaultUnitID.value)?.name||units.value[0].name;showCreate.value=true}
async function create(){try{const made=await CreateTask({...draft}) as Task;showCreate.value=false;Object.assign(draft,{name:'',kind:'main',parentId:'',issuer:'',unit:'',publishDate:today(),dueDate:today(),taskType:'code'});await refresh();selected.value=made;message.value='任务已创建'}catch(e){message.value=String(e)}}
async function save(){if(!selected.value)return;try{await UpdateTask(selected.value);await refresh();message.value='任务详情已保存'}catch(e){message.value=String(e)}}
async function setStatus(value:Status){if(!selected.value)return;try{await UpdateTaskStatus(selected.value.id,value);await refresh();message.value='状态已更新'}catch(e){message.value=String(e)}}
async function exportData(){try{await ExportData();message.value='数据已导出'}catch(e){message.value=String(e)}} async function importData(){try{await ImportData();await refresh();message.value='数据已导入'}catch(e){message.value=String(e)}}
async function addUnit(){try{await CreateUnit(newUnit.value);newUnit.value='';await refresh();message.value='单位已创建'}catch(e){message.value=String(e)}}
async function renameUnit(unit:Unit){const name=window.prompt('修改单位名称',unit.name);if(name===null)return;try{await UpdateUnit(unit.id,name);await refresh();message.value='单位已更新'}catch(e){message.value=String(e)}}
async function setDefault(id:string){try{await SetDefaultUnit(id);await refresh();message.value='默认单位已设置'}catch(e){message.value=String(e)}}
onMounted(()=>refresh().catch(e=>message.value=String(e)))
</script>

<template><main class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">✓</span><div><b>TaskFlow</b><small>工作任务管理器</small></div></div><p class="side-title">任务概览</p><button v-for="s in ['all','in_progress','completed','cancelled']" :key="s" class="nav-item" :class="{active:status===s}" @click="status=s"><span>{{s==='all'?'全部任务':statusText[s as Status]}}</span><em>{{s==='all'?tasks.length:tasks.filter(t=>t.status===s).length}}</em></button><button class="nav-item" @click="showUnits=true"><span>单位管理</span><em>{{units.length}}</em></button><div class="stats"><span>进行中</span><strong>{{tasks.filter(t=>t.status==='in_progress').length}}</strong><span>已逾期</span><strong class="danger">{{tasks.filter(overdue).length}}</strong></div></aside><section class="workspace"><header><div><p class="eyebrow">工作空间</p><h1>我的任务</h1></div><div class="actions"><button @click="importData">导入 JSON</button><button @click="exportData">导出 JSON</button><button class="primary" @click="openCreate">＋ 新建任务</button></div></header><div class="toolbar"><input v-model="query" placeholder="搜索任务名、下发人或单位"><select v-model="type"><option value="all">全部类型</option><option value="code">代码</option><option value="document">文档</option><option value="support">支持</option></select><span>{{filtered.length}} 项结果</span></div><div class="task-list"><template v-for="main in mains.filter(isVisible)" :key="main.id"><button class="task-row" :class="{selected:selected?.id===main.id}" @click="selected=main"><span>◆</span><span class="task-name">{{main.name}}<small>{{main.unit}} · {{main.issuer}} · {{typeText[main.taskType]}}</small></span><span class="date" :class="{overdue:overdue(main)}">{{main.dueDate}}</span><span class="badge" :class="main.status">{{statusText[main.status]}}</span></button><button v-for="child in tasks.filter(t=>t.kind==='branch'&&t.parentId===main.id&&filtered.some(x=>x.id===t.id))" :key="child.id" class="task-row child" :class="{selected:selected?.id===child.id}" @click="selected=child"><span>↳</span><span class="task-name">{{child.name}}<small>{{child.unit}} · {{child.issuer}} · {{typeText[child.taskType]}}</small></span><span class="date">{{child.dueDate}}</span><span class="badge" :class="child.status">{{statusText[child.status]}}</span></button></template><div v-if="!filtered.length" class="empty">暂无任务。点击右上角“新建任务”开始创建。</div></div></section><aside class="details" v-if="selected"><div class="details-heading"><div><p class="eyebrow">任务详情</p><h2>{{selected.name}}</h2></div><span class="badge" :class="selected.status">{{statusText[selected.status]}}</span></div><div class="status-buttons"><button v-for="s in ['in_progress','completed','cancelled']" :class="{chosen:selected.status===s}" @click="setStatus(s as Status)">{{statusText[s as Status]}}</button></div><div class="fields"><div class="field"><small>单位</small><span>{{selected.unit}}</span></div><div class="field"><small>任务层级</small><span>{{selected.kind==='main'?'主线任务':'支线任务'}}</span></div><div class="field"><small>下发人</small><span>{{selected.issuer}}</span></div><div class="field"><small>截止日期</small><span>{{selected.dueDate}}</span></div></div><label>产出物<textarea v-model="selected.deliverable" placeholder="填写交付物、链接或文件位置"/></label><label>总结<textarea v-model="selected.summary" placeholder="填写任务进展、结论或复盘"/></label><button class="primary save" @click="save">保存详情</button></aside><aside class="details empty" v-else>选择一项任务以查看详情</aside><div v-if="showCreate" class="modal-backdrop"><form class="modal" @submit.prevent="create"><div class="modal-title"><div><p class="eyebrow">创建任务</p><h2>添加新的工作项</h2></div><button type="button" class="close" @click="showCreate=false">×</button></div><div class="form-grid"><label>单位<select v-model="draft.unit" required><option value="">请选择单位</option><option v-for="unit in units" :value="unit.name">{{unit.name}}</option></select></label><label>任务名<input v-model="draft.name" required></label><label>下发人<input v-model="draft.issuer" required></label><label>任务层级<select v-model="draft.kind"><option value="main">主线任务</option><option value="branch">支线任务</option></select></label><label v-if="draft.kind==='branch'">所属主线任务<select v-model="draft.parentId" required><option value="">请选择</option><option v-for="task in mains" :value="task.id">{{task.name}}</option></select></label><label>发布日期<input v-model="draft.publishDate" type="date" required></label><label>截止日期<input v-model="draft.dueDate" type="date" required></label><label>任务类型<select v-model="draft.taskType"><option value="code">代码</option><option value="document">文档</option><option value="support">支持</option></select></label></div><p class="hint">产出物和总结可在创建后于任务详情中补充。</p><div class="actions"><button type="button" @click="showCreate=false">取消</button><button class="primary" type="submit">创建任务</button></div></form></div><div v-if="showUnits" class="modal-backdrop"><div class="modal"><div class="modal-title"><div><p class="eyebrow">单位管理</p><h2>单位列表</h2></div><button class="close" @click="showUnits=false">×</button></div><form class="unit-add" @submit.prevent="addUnit"><input v-model="newUnit" required placeholder="输入单位名称"><button class="primary">新增单位</button></form><div class="unit-list"><div v-for="unit in units" :key="unit.id" class="unit-row"><span>{{unit.name}}</span><em v-if="unit.id===defaultUnitID">默认单位</em><button @click="setDefault(unit.id)">{{unit.id===defaultUnitID?'已设默认':'设为默认'}}</button><button @click="renameUnit(unit)">修改</button></div><div v-if="!units.length" class="empty">尚未创建单位。</div></div></div></div><button v-if="message" class="toast" @click="message=''">{{message}} ×</button></main></template>
